head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > gotoMonth]<br/>Calendar 컴포넌트의 선택 월을 설정하며 지정한 날짜로 이동합니다.",
    "validation" : [
        "month(필수) 파라미터로 이동할 월을 1~12 범위의 Number 또는 String 으로 설정합니다.",
        "'05', '5', 5 모두 동일하게 5월로 이동합니다.",
        "연도와 일자는 기존값을 유지합니다.",
        "날짜 이동 후 getValue() 메소드의 반환값이 이동 전과 다르면 onchange 이벤트가 발생합니다.",
        "현재 일자가 이동할 월의 최대 일수를 초과하는 경우 해당 월의 마지막 날짜로 설정됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cList = $c.gcm.createCList({});
    let eList = $c.gcm.createEList(["onchange"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11
}



// gotoMonth 호출 (선택된 케이스에 따라 분기)
// validation:
//  - 1~12 범위의 Number/String 모두 동일 처리
//  - 연도와 일자는 기존값 유지
//  - 현재 일자가 이동할 월의 최대 일수 초과 시 해당 월의 마지막 날짜로 조정
scwin.btn_gotoMonth_onclick = function (e) {
    let caseId = con_gotoCase.getValue();
    let arg, argDesc;

    // 케이스 5: 일자가 31일인 상태에서 2월(2일)로 이동 → 28일로 조정되는지 확인
    // 사전 셋업: gotoCalendar('20250131') 호출하여 1월 31일로 이동
    if (caseId === '5') {
        target1.gotoCalendar('20250131');
    }

    if (caseId === '1') {
        arg = 5;
        argDesc = "5 (Number)";
    } else if (caseId === '2') {
        arg = '5';
        argDesc = "'5' (String)";
    } else if (caseId === '3') {
        arg = '05';
        argDesc = "'05' (String)";
    } else if (caseId === '4') {
        arg = 2;
        argDesc = "2 (Number) / 초기 일자 11 유지 검증";
    } else if (caseId === '5') {
        arg = 2;
        argDesc = "2 (Number) / 사전 1/31 → 2월 이동 시 일자 보정 검증";
    }

    let beforeValue = target1.getValue();
    target1.gotoMonth(arg);
    let afterValue = target1.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue(
        "[gotoMonth 호출 전 getValue()] '" + beforeValue + "'"
        + " / [gotoMonth 인자] " + argDesc
        + " / [gotoMonth 호출 후 getValue()] '" + afterValue + "'"
    );
};



// 날짜 이동 후 getValue() 반환값이 이동 전과 다르면 onchange 이벤트 발생
// @spec validation
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생] 선택일이 변경되어 onchange 핸들러 호출됨");
};
